insert into tag_keyword(tag_id, is_positive, keyword, keyword_forms, is_regex)
select tag.id, cte.is_positive, cte.keyword, cte.keyword_forms, cte.is_regex from cte
join tag on cte.tag_label = tag.label
where tag.enabled = true
  and not exists (
    select 1 from tag_keyword k
    where k.tag_id = tag.id
);
